// scan.Mapper[*T] without reflection: maps columns to fields by index.
func operationScanMapper(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*Operation, error)) {
	// resolve the column positions once per query, not per row
	type target struct {
		idx int
		dst func(o *Operation) any
	}
	targets := make([]target, 0, 25)
	for i, col := range cols {
		switch col {
		case "id":
			targets = append(targets, target{i, func(o *Operation) any { return &o.ID }})
		case "created_at":
			targets = append(targets, target{i, func(o *Operation) any { return &o.CreatedAt }})
		case "updated_at":
			targets = append(targets, target{i, func(o *Operation) any { return &o.UpdatedAt }})
		case "container_id":
			targets = append(targets, target{i, func(o *Operation) any { return &o.ContainerID }})
		case "field_id":
			targets = append(targets, target{i, func(o *Operation) any { return &o.FieldID }})
		case "kind":
			targets = append(targets, target{i, func(o *Operation) any { return &o.Kind }})
		case "trace_id":
			targets = append(targets, target{i, func(o *Operation) any { return &o.TraceID }})
		case "credential_id":
			targets = append(targets, target{i, func(o *Operation) any { return &o.CredentialID }})
		case "credential_scopes":
			targets = append(targets, target{i, func(o *Operation) any { return &o.CredentialScopes }})
		case "result":
			targets = append(targets, target{i, func(o *Operation) any { return &o.Result }})
		case "started_at":
			targets = append(targets, target{i, func(o *Operation) any { return &o.StartedAt }})
		case "completed_at":
			targets = append(targets, target{i, func(o *Operation) any { return &o.CompletedAt }})
		case "status":
			targets = append(targets, target{i, func(o *Operation) any { return &o.Status }})
		case "surface":
			targets = append(targets, target{i, func(o *Operation) any { return &o.Surface }})
		case "after_item_id":
			targets = append(targets, target{i, func(o *Operation) any { return &o.AfterItemID }})
		case "processed":
			targets = append(targets, target{i, func(o *Operation) any { return &o.Processed }})
		case "error":
			targets = append(targets, target{i, func(o *Operation) any { return &o.Error }})
		case "created_by":
			targets = append(targets, target{i, func(o *Operation) any { return &o.CreatedBy }})
		case "payload":
			targets = append(targets, target{i, func(o *Operation) any { return &o.Payload }})
		case "prepared":
			targets = append(targets, target{i, func(o *Operation) any { return &o.Prepared }})
		case "matched":
			targets = append(targets, target{i, func(o *Operation) any { return &o.Matched }})
		case "updated":
			targets = append(targets, target{i, func(o *Operation) any { return &o.Updated }})
		case "failed":
			targets = append(targets, target{i, func(o *Operation) any { return &o.Failed }})
		case "progress":
			targets = append(targets, target{i, func(o *Operation) any { return &o.Progress }})
		case "failures":
			targets = append(targets, target{i, func(o *Operation) any { return &o.Failures }})
		}
	}

	return func(row *scan.Row) (any, error) {
			o := new(Operation)
			for _, t := range targets {
				row.ScheduleScanByIndex(t.idx, t.dst(o))
			}
			return o, nil
		}, func(v any) (*Operation, error) {
			return v.(*Operation), nil
		}
}

// FindOperation retrieves a single record by primary key
// If cols is empty Find will return all columns.
func FindOperation(ctx context.Context, exec bob.Executor, IDPK string, cols ...string) (*Operation, error) {
	if len(cols) == 0 {
		return Operations.Query(
			sm.Where(Operations.Columns.ID.EQ(sqlite.Arg(IDPK))),
		).One(ctx, exec)
	}

	return Operations.Query(
		sm.Where(Operations.Columns.ID.EQ(sqlite.Arg(IDPK))),
		sm.Columns(Operations.Columns.Only(cols...)),
	).One(ctx, exec)
}

// OperationExists checks the presence of a single record by primary key
func OperationExists(ctx context.Context, exec bob.Executor, IDPK string) (bool, error) {
	return Operations.Query(
		sm.Where(Operations.Columns.ID.EQ(sqlite.Arg(IDPK))),
	).Exists(ctx, exec)
}

// AfterQueryHook is called after Operation is retrieved from the database
func (o *Operation) AfterQueryHook(ctx context.Context, exec bob.Executor, queryType bob.QueryType) error {
	var err error

	switch queryType {
	case bob.QueryTypeSelect:
		ctx, err = Operations.AfterSelectHooks.RunHooks(ctx, exec, OperationSlice{o})
	case bob.QueryTypeInsert:
		ctx, err = Operations.AfterInsertHooks.RunHooks(ctx, exec, OperationSlice{o})
	case bob.QueryTypeUpdate:
		ctx, err = Operations.AfterUpdateHooks.RunHooks(ctx, exec, OperationSlice{o})
	case bob.QueryTypeDelete:
		ctx, err = Operations.AfterDeleteHooks.RunHooks(ctx, exec, OperationSlice{o})

	}

	return err
}

// primaryKeyVals returns the primary key values of the Operation
func (o *Operation) primaryKeyVals() bob.Expression {
	return sqlite.Arg(o.ID)
}

func (o *Operation) pkEQ() dialect.Expression {
	return sqlite.Quote("operations", "id").EQ(bob.ExpressionFunc(func(ctx context.Context, w io.StringWriter, d bob.Dialect, start int) ([]any, error) {
		return o.primaryKeyVals().WriteSQL(ctx, w, d, start)
	}))
}

// Update uses an executor to update the Operation
func (o *Operation) Update(ctx context.Context, exec bob.Executor, s *OperationSetter) error {
	v, err := Operations.Update(s.UpdateMod(), um.Where(o.pkEQ())).One(ctx, exec)
	if err != nil {
		return err
	}

	o.R = v.R
	*o = *v

	return nil
}

// Delete deletes a single Operation record with an executor
func (o *Operation) Delete(ctx context.Context, exec bob.Executor) error {
	_, err := Operations.Delete(dm.Where(o.pkEQ())).Exec(ctx, exec)
	return err
}

// Reload refreshes the Operation using the executor
func (o *Operation) Reload(ctx context.Context, exec bob.Executor) error {
	o2, err := Operations.Query(
		sm.Where(Operations.Columns.ID.EQ(sqlite.Arg(o.ID))),
	).One(ctx, exec)
	if err != nil {
		return err
	}
	o2.R = o.R
	*o = *o2

	return nil
}

// AfterQueryHook is called after OperationSlice is retrieved from the database
func (o OperationSlice) AfterQueryHook(ctx context.Context, exec bob.Executor, queryType bob.QueryType) error {
	var err error

	switch queryType {
	case bob.QueryTypeSelect:
		ctx, err = Operations.AfterSelectHooks.RunHooks(ctx, exec, o)
	case bob.QueryTypeInsert:
		ctx, err = Operations.AfterInsertHooks.RunHooks(ctx, exec, o)
	case bob.QueryTypeUpdate:
		ctx, err = Operations.AfterUpdateHooks.RunHooks(ctx, exec, o)
	case bob.QueryTypeDelete:
		ctx, err = Operations.AfterDeleteHooks.RunHooks(ctx, exec, o)

	}

	return err
}

func (o OperationSlice) pkIN() dialect.Expression {
	if len(o) == 0 {
		return sqlite.Raw("NULL")
	}

	return sqlite.Quote("operations", "id").In(bob.ExpressionFunc(func(ctx context.Context, w io.StringWriter, d bob.Dialect, start int) ([]any, error) {
		pkPairs := make([]bob.Expression, len(o))
		for i, row := range o {
			pkPairs[i] = row.primaryKeyVals()
		}
		return bob.ExpressSlice(ctx, w, d, start, pkPairs, "", ", ", "")
	}))
}

// copyMatchingRows finds models in the given slice that have the same primary key
// then it first copies the existing relationships from the old model to the new model
// and then replaces the old model in the slice with the new model
func (o OperationSlice) copyMatchingRows(from ...*Operation) {
	fromByPK := make(map[string]*Operation, len(from))
	for _, new := range from {
		// keep the first row for each key, like the nested loop did
		if _, ok := fromByPK[new.ID]; !ok {
			fromByPK[new.ID] = new
		}
	}

	for i, old := range o {
		new, ok := fromByPK[old.ID]
		if !ok {
			continue
		}
		new.R = old.R
		o[i] = new
	}
}

// UpdateMod modifies an update query with "WHERE primary_key IN (o...)"
func (o OperationSlice) UpdateMod() bob.Mod[*dialect.UpdateQuery] {
	return bob.ModFunc[*dialect.UpdateQuery](func(q *dialect.UpdateQuery) {
		q.AppendHooks(func(ctx context.Context, exec bob.Executor) (context.Context, error) {
			return Operations.BeforeUpdateHooks.RunHooks(ctx, exec, o)
		})

		q.AppendLoader(bob.LoaderFunc(func(ctx context.Context, exec bob.Executor, retrieved any) error {
			var err error
			switch retrieved := retrieved.(type) {
			case *Operation:
				o.copyMatchingRows(retrieved)
			case []*Operation:
				o.copyMatchingRows(retrieved...)
			case OperationSlice:
				o.copyMatchingRows(retrieved...)
			default:
				// If the retrieved value is not a Operation or a slice of Operation
				// then run the AfterUpdateHooks on the slice
				_, err = Operations.AfterUpdateHooks.RunHooks(ctx, exec, o)
			}

			return err
		}))

		q.AppendWhere(o.pkIN())
	})
}

// DeleteMod modifies an delete query with "WHERE primary_key IN (o...)"
func (o OperationSlice) DeleteMod() bob.Mod[*dialect.DeleteQuery] {
	return bob.ModFunc[*dialect.DeleteQuery](func(q *dialect.DeleteQuery) {
		q.AppendHooks(func(ctx context.Context, exec bob.Executor) (context.Context, error) {
			return Operations.BeforeDeleteHooks.RunHooks(ctx, exec, o)
		})

		q.AppendLoader(bob.LoaderFunc(func(ctx context.Context, exec bob.Executor, retrieved any) error {
			var err error
			switch retrieved := retrieved.(type) {
			case *Operation:
				o.copyMatchingRows(retrieved)
			case []*Operation:
				o.copyMatchingRows(retrieved...)
			case OperationSlice:
				o.copyMatchingRows(retrieved...)
			default:
				// If the retrieved value is not a Operation or a slice of Operation
				// then run the AfterDeleteHooks on the slice
				_, err = Operations.AfterDeleteHooks.RunHooks(ctx, exec, o)
			}

			return err
		}))

		q.AppendWhere(o.pkIN())
	})
}

func (o OperationSlice) UpdateAll(ctx context.Context, exec bob.Executor, vals OperationSetter) error {
	if len(o) == 0 {
		return nil
	}

	_, err := Operations.Update(vals.UpdateMod(), o.UpdateMod()).All(ctx, exec)
	return err
}

func (o OperationSlice) DeleteAll(ctx context.Context, exec bob.Executor) error {
	if len(o) == 0 {
		return nil
	}

	_, err := Operations.Delete(o.DeleteMod()).Exec(ctx, exec)
	return err
}

func (o OperationSlice) ReloadAll(ctx context.Context, exec bob.Executor) error {
	if len(o) == 0 {
		return nil
	}

	o2, err := Operations.Query(sm.Where(o.pkIN())).All(ctx, exec)
	if err != nil {
		return err
	}

	o.copyMatchingRows(o2...)

	return nil
}

// OperationItems starts a query for related objects on operation_items
func (o *Operation) OperationItems(mods ...bob.Mod[*dialect.SelectQuery]) OperationItemsQuery {
	return OperationItems.Query(append(mods,
		sm.Where(OperationItems.Columns.OperationID.EQ(sqlite.Arg(o.ID))),
	)...)
}

func (os OperationSlice) OperationItems(mods ...bob.Mod[*dialect.SelectQuery]) OperationItemsQuery {
	PKArgSlice := make([]bob.Expression, len(os))
	for i, o := range os {
		PKArgSlice[i] = sqlite.ArgGroup(o.ID)
	}
	PKArgExpr := sqlite.Group(PKArgSlice...)

	return OperationItems.Query(append(mods,
		sm.Where(sqlite.Group(OperationItems.Columns.OperationID).OP("IN", PKArgExpr)),
	)...)
}

// ContainerResource starts a query for related objects on resources
func (o *Operation) ContainerResource(mods ...bob.Mod[*dialect.SelectQuery]) ResourcesQuery {
	return Resources.Query(append(mods,
		sm.Where(Resources.Columns.ID.EQ(sqlite.Arg(o.ContainerID))),
	)...)
}

func (os OperationSlice) ContainerResource(mods ...bob.Mod[*dialect.SelectQuery]) ResourcesQuery {
	PKArgSlice := make([]bob.Expression, len(os))
	for i, o := range os {
		PKArgSlice[i] = sqlite.ArgGroup(o.ContainerID)
	}
	PKArgExpr := sqlite.Group(PKArgSlice...)

	return Resources.Query(append(mods,
		sm.Where(sqlite.Group(Resources.Columns.ID).OP("IN", PKArgExpr)),
	)...)
}

func insertOperationOperationItems0(ctx context.Context, exec bob.Executor, operationItems1 []*OperationItemSetter, operation0 *Operation) (OperationItemSlice, error) {
	for i := range operationItems1 {
		operationItems1[i].OperationID = omit.From(operation0.ID)
	}

	ret, err := OperationItems.Insert(bob.ToMods(operationItems1...)).All(ctx, exec)
	if err != nil {
		return ret, fmt.Errorf("insertOperationOperationItems0: %w", err)
	}

	return ret, nil
}

func attachOperationOperationItems0(ctx context.Context, exec bob.Executor, count int, operationItems1 OperationItemSlice, operation0 *Operation) (OperationItemSlice, error) {
	setter := &OperationItemSetter{
		OperationID: omit.From(operation0.ID),
	}

	err := operationItems1.UpdateAll(ctx, exec, *setter)
	if err != nil {
		return nil, fmt.Errorf("attachOperationOperationItems0: %w", err)
	}

	return operationItems1, nil
}

func (operation0 *Operation) InsertOperationItems(ctx context.Context, exec bob.Executor, related ...*OperationItemSetter) error {
	if len(related) == 0 {
		return nil
	}

	var err error

	operationItems1, err := insertOperationOperationItems0(ctx, exec, related, operation0)
	if err != nil {
		return err
	}

	operation0.R.OperationItems = append(operation0.R.OperationItems, operationItems1...)

	return nil
}

func (operation0 *Operation) AttachOperationItems(ctx context.Context, exec bob.Executor, related ...*OperationItem) error {
	if len(related) == 0 {
		return nil
	}

	var err error
	operationItems1 := OperationItemSlice(related)

	_, err = attachOperationOperationItems0(ctx, exec, len(related), operationItems1, operation0)
	if err != nil {
		return err
	}

	operation0.R.OperationItems = append(operation0.R.OperationItems, operationItems1...)

	return nil
}

