type operationWhere[Q sqlite.Filterable] struct {
	cols             operationColumns
	ID               sqlite.WhereMod[Q, string]
	CreatedAt        sqlite.WhereMod[Q, time.Time]
	UpdatedAt        sqlite.WhereMod[Q, time.Time]
	ContainerID      sqlite.WhereNullMod[Q, string]
	FieldID          sqlite.WhereMod[Q, string]
	Kind             sqlite.WhereMod[Q, string]
	TraceID          sqlite.WhereMod[Q, string]
	CredentialID     sqlite.WhereNullMod[Q, string]
	CredentialScopes sqlite.WhereMod[Q, types.JSON[[]string]]
	Result           sqlite.WhereMod[Q, types.JSON[json.RawMessage]]
	StartedAt        sqlite.WhereNullMod[Q, time.Time]
	CompletedAt      sqlite.WhereNullMod[Q, time.Time]
	Status           sqlite.WhereMod[Q, string]
	Surface          sqlite.WhereMod[Q, string]
	AfterItemID      sqlite.WhereMod[Q, string]
	Processed        sqlite.WhereMod[Q, int64]
	Error            sqlite.WhereMod[Q, string]
	CreatedBy        sqlite.WhereMod[Q, string]
	Payload          sqlite.WhereMod[Q, types.JSON[json.RawMessage]]
	Prepared         sqlite.WhereMod[Q, bool]
	Matched          sqlite.WhereMod[Q, int64]
	Updated          sqlite.WhereMod[Q, int64]
	Failed           sqlite.WhereMod[Q, int64]
	Progress         sqlite.WhereMod[Q, int64]
	Failures         sqlite.WhereMod[Q, types.JSON[[]model.OperationFailure]]
	R                operationWhereR[Q]
}

func (operationWhere[Q]) AliasedAs(alias string) operationWhere[Q] {
	return buildOperationWhere[Q](buildOperationColumns(alias))
}

func buildOperationWhere[Q sqlite.Filterable](cols operationColumns) operationWhere[Q] {
	return operationWhere[Q]{
		cols:             cols,
		ID:               sqlite.Where[Q, string](cols.ID.Expression),
		CreatedAt:        sqlite.Where[Q, time.Time](cols.CreatedAt.Expression),
		UpdatedAt:        sqlite.Where[Q, time.Time](cols.UpdatedAt.Expression),
		ContainerID:      sqlite.WhereNull[Q, string](cols.ContainerID.Expression),
		FieldID:          sqlite.Where[Q, string](cols.FieldID.Expression),
		Kind:             sqlite.Where[Q, string](cols.Kind.Expression),
		TraceID:          sqlite.Where[Q, string](cols.TraceID.Expression),
		CredentialID:     sqlite.WhereNull[Q, string](cols.CredentialID.Expression),
		CredentialScopes: sqlite.Where[Q, types.JSON[[]string]](cols.CredentialScopes.Expression),
		Result:           sqlite.Where[Q, types.JSON[json.RawMessage]](cols.Result.Expression),
		StartedAt:        sqlite.WhereNull[Q, time.Time](cols.StartedAt.Expression),
		CompletedAt:      sqlite.WhereNull[Q, time.Time](cols.CompletedAt.Expression),
		Status:           sqlite.Where[Q, string](cols.Status.Expression),
		Surface:          sqlite.Where[Q, string](cols.Surface.Expression),
		AfterItemID:      sqlite.Where[Q, string](cols.AfterItemID.Expression),
		Processed:        sqlite.Where[Q, int64](cols.Processed.Expression),
		Error:            sqlite.Where[Q, string](cols.Error.Expression),
		CreatedBy:        sqlite.Where[Q, string](cols.CreatedBy.Expression),
		Payload:          sqlite.Where[Q, types.JSON[json.RawMessage]](cols.Payload.Expression),
		Prepared:         sqlite.Where[Q, bool](cols.Prepared.Expression),
		Matched:          sqlite.Where[Q, int64](cols.Matched.Expression),
		Updated:          sqlite.Where[Q, int64](cols.Updated.Expression),
		Failed:           sqlite.Where[Q, int64](cols.Failed.Expression),
		Progress:         sqlite.Where[Q, int64](cols.Progress.Expression),
		Failures:         sqlite.Where[Q, types.JSON[[]model.OperationFailure]](cols.Failures.Expression),
		R:                operationWhereR[Q]{cols: cols},
	}
}

// operationWhereR holds the relationship-based filters of
// operationWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type operationWhereR[Q sqlite.Filterable] struct {
	cols operationColumns
}

// HasOperationItems filters parents that have a matching OperationItems using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to OperationItems).
func (w operationWhereR[Q]) HasOperationItems(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := sqlite.Select(
		sm.Columns(sqlite.Raw("1")),
		sm.From(OperationItems.NameExpr()),
		sm.Where(OperationItems.Columns.OperationID.EQ(w.cols.ID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: sqlite.Exists(q)}
}

// HasContainerResource filters parents that have a matching ContainerResource using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Resources).
func (w operationWhereR[Q]) HasContainerResource(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := sqlite.Select(
		sm.Columns(sqlite.Raw("1")),
		sm.From(Resources.NameExpr()),
		sm.Where(Resources.Columns.ID.EQ(w.cols.ContainerID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: sqlite.Exists(q)}
}
